package org.sormus.downloads;
public final class TransferProtocolTest {
 public static void main(String[] args)throws Exception{if(!TransferProtocol.server("http://192.168.1.10:7041/").equals("http://192.168.1.10:7041"))throw new Error();for(String s:new String[]{"http://example.org:7041","http://127.0.0.1@evil.test","file:///test","http://192.168.1.1:0","http://192.168.1.1/?token=secret","http://192.168.1.1/api","http://192.168.1.1#secret","http://8.8.8.8","http://192.168.999.1"}){boolean failed=false;try{TransferProtocol.server(s);}catch(Exception e){failed=true;}if(!failed)throw new Error("Allowed "+s);}if(!TransferProtocol.link("magnet:?xt=urn:btih:0123456789012345678901234567890123456789")||!TransferProtocol.link("https://example.org/file.torrent")||TransferProtocol.link("javascript:alert(1)")||TransferProtocol.link("https://a.test/\nsecret")||TransferProtocol.link("https://user:pass@example.org/file"))throw new Error();System.out.println("Phone address and link boundaries passed.");}
}
